    import collections
    V=collections.Counter(d["verdict"] for d in INV)
    L=collections.Counter(d["layer"] for d in INV)
    NAMES={"CONFIRM":"устояло","WEAK":"ослаблено","DISSOLVE":"растворилось","ATTRIB":"отнесено к слою","UNRES":"нет разрешения","RETRACT":"отозвано"}
    LN={"morph":"аффиксный слой","freq":"частотное распределение","seq":"последовательность","line":"позиция в строке","div":"деления рукописи","none":"—"}
    print(f"ЗАПИСЕЙ В ИНВЕНТАРЕ: {len(INV)}\n")
    print("По исходу:")
    for k,n in V.most_common(): print(f"  {NAMES[k]:>18s} {n:3d}")
    print("\nПо слою, где живёт явление:")
    for k,n in L.most_common(): print(f"  {LN[k]:>24s} {n:3d}")
    own=sum(1 for d in INV if "наше" in d["whose"])
    print(f"\nзаявлено как наше: {own} из {len(INV)}; остальное — проверка чужих утверждений")
    tr=sum(1 for d in INV if d.get("transcr"))
    print(f"проверено на шести транскрипциях: {tr}")
